function main(): void {
  const b = Buffer.from('hello');
  console.log(typeof b.at, typeof b.copy, typeof b.fill, typeof b.swap16, typeof b.readIntBE, typeof b.indexOf, typeof b.toString);
  const a = [1, 2, 3];
  console.log(typeof a.at, typeof a.findLast, typeof a.copyWithin);
  const f = b.includes;
  console.log(typeof f, f.call(b, 'ell'));
}
